
from pathlib import Path
from datetime import datetime,timezone
import base64,hashlib,json,os,socket,subprocess
repo=Path('/home/jovyan/shares/SR003.nfs2/GENATATOR_PIPELINE/diploma_yandex_graphs');phase=repo/'experiments_iclr/postsubmission_20260930'
assert Path.cwd().resolve()==repo and socket.gethostname()=='anogena-2-0'
uuids=subprocess.check_output(['nvidia-smi','--query-gpu=uuid','--format=csv,noheader'],text=True,timeout=15).split()
assert uuids==['GPU-44039938-fd82-41d2-fefd-de71514e2fac']
cfg={'operation': 'shared_private_transfer_complete39_common_negative_owned_operation_20261006_v1', 'source_name': 'shared_private_transfer_complete39_common_negative_diagnostic_preparation_20261006_v1', 'source_sha256': '2a7aa40400fb944dc83144f49575653b32c404a749bd21f34184d09142ce0b53', 'release_sha256': '827882735a8b14ea23e478e537ec00045980504dcf5d3a012aba3c23b112f7d2', 'files': [{'path': 'shared_private_transfer_complete39_common_negative_diagnostic_preparation_20261006_v1/analyze_common_negatives.py', 'bytes': 10626, 'sha256': '2a7aa40400fb944dc83144f49575653b32c404a749bd21f34184d09142ce0b53', 'base64': ''}, {'path': 'shared_private_transfer_complete39_common_negative_diagnostic_preparation_20261006_v1/BINDINGS.json', 'bytes': 10893, 'sha256': '99981bad6baf3d6e1596d9064695fc07588917fc6f25eb74cabf9b1d2264524a', 'base64': ''}], 'supervisor_base64': '', 'supervisor_sha256': '18c1a2abf440dc2191de4e5c3dc5094bec73d3d390c468d6b77aba44e9630e1e', 'release_base64': ''};target=phase/cfg['operation'];assert not target.exists()
def sha(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()
for row in cfg['files']:
 rel=Path(row['path']);assert not rel.is_absolute() and '..' not in rel.parts and rel.parts[0]==cfg['source_name']
 value=base64.b64decode(row['base64'],validate=True);assert len(value)==row['bytes'] and hashlib.sha256(value).hexdigest()==row['sha256']
 path=phase/rel
 if path.exists():assert path.is_file() and not path.is_symlink() and sha(path)==row['sha256']
 else:
  path.parent.mkdir(parents=True,exist_ok=True)
  with path.open('xb') as f:f.write(value)
  path.chmod(0o444)
source=phase/cfg['source_name']/'analyze_common_negatives.py';assert sha(source)==cfg['source_sha256']
release=base64.b64decode(cfg['release_base64'],validate=True);assert hashlib.sha256(release).hexdigest()==cfg['release_sha256']
active=json.loads(release);assert active['enabled'] is True and active['source_review_approved'] is True and active['artifact_root']==str(phase) and active['TEST_access'] is False and active['model_execution'] is False and active['checkpoint_reselection'] is False
native=phase/'native_ncn_runtime_20261005_v1/.venv/bin/python';assert native.is_file()
environment={'CUDA_VISIBLE_DEVICES':'','OMP_NUM_THREADS':'1','MKL_NUM_THREADS':'1','OPENBLAS_NUM_THREADS':'1','PYTHONDONTWRITEBYTECODE':'1','PYTHONPATH':str(repo/'.venv/lib/python3.11/site-packages')}
assert Path(environment['PYTHONPATH']).is_dir()
target.mkdir()
code=base64.b64decode(cfg['supervisor_base64'],validate=True);assert hashlib.sha256(code).hexdigest()==cfg['supervisor_sha256']
for name,value in [('supervise_once.py',code),('ROOT_ANALYSIS_RELEASE.json',release)]:
 with (target/name).open('xb') as f:f.write(value)
 (target/name).chmod(0o444)
configuration={'argv':[str(native),'-B',str(source),'--release',str(target/'ROOT_ANALYSIS_RELEASE.json')], 'child_environment':environment,
 'runtime_spec':{'native_executable':str(native),'torch':'2.1.2+cu118','device':'cpu','existing_reviewed_repo_site':environment['PYTHONPATH'],'source':'Prior successful D2 exact CPU reader config; reader enforces runtime version'},
 'source_sha256':cfg['source_sha256'],'release_sha256':cfg['release_sha256']}
with (target/'CONFIG.json').open('x') as f:json.dump(configuration,f,indent=2,sort_keys=True);f.write('\n')
(target/'CONFIG.json').chmod(0o444)
with (target/'supervisor.stdout').open('xb') as out,(target/'supervisor.stderr').open('xb') as err:
 process=subprocess.Popen(['/usr/bin/python3','-I','-S','-B',str(target/'supervise_once.py')],cwd=str(repo),stdin=subprocess.DEVNULL,stdout=out,stderr=err,start_new_session=True)
 raw=(Path('/proc')/str(process.pid)/'stat').read_text();identity={'PID':process.pid,'start_ticks':int(raw[raw.rfind(')')+2:].split()[19]),'pgid':os.getpgid(process.pid),'sid':os.getsid(process.pid)}
assert identity['pgid']==identity['sid']==process.pid
receipt={'UTC':datetime.now(timezone.utc).isoformat(),'hostname':socket.gethostname(),'GPU_UUIDs':uuids,'supervisor_identity':identity,'operation':cfg['operation'],'source_sha256':sha(source),'bindings_sha256':sha(source.parent/'BINDINGS.json'),'supervisor_sha256':sha(target/'supervise_once.py'),'release_sha256':sha(target/'ROOT_ANALYSIS_RELEASE.json'),'config_sha256':sha(target/'CONFIG.json'),'child_argv':configuration['argv'],'CPU_only':True,'limits_seconds':600,'RSS_limit_bytes':8*1024**3,'attempts':1,'retry':False}
with (target/'LAUNCH_RECEIPT.json').open('x') as f:json.dump(receipt,f,indent=2,sort_keys=True);f.write('\n')
print(json.dumps(receipt))
